import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"設定と上限","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md","lastUpdated":1793464466000}`),a={name:`reference/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="設定と上限" tabindex="-1">設定と上限 <a class="header-anchor" href="#設定と上限" aria-label="Permalink to “設定と上限”">​</a></h1><h2 id="実行時設定" tabindex="-1">実行時設定 <a class="header-anchor" href="#実行時設定" aria-label="Permalink to “実行時設定”">​</a></h2><table tabindex="0"><thead><tr><th>名前</th><th>意味</th></tr></thead><tbody><tr><td>AUTH_MODE</td><td>passkeyで新管理画面を使用</td></tr><tr><td>AUTH_ORIGIN</td><td>固定された管理画面Origin。HTTPS、末尾スラッシュなし</td></tr><tr><td>AUTH_SECRET</td><td>環境ごとの署名Secret。32文字以上</td></tr><tr><td>ADMIN_TOKEN</td><td>初回Superuser登録用。32文字以上</td></tr><tr><td>JEV_API_KEY</td><td>Jevの実判定用キー</td></tr><tr><td>JEV_MODEL</td><td>初回設定に使うモデル名</td></tr><tr><td>DAILY_REQUEST_BUDGET</td><td>初回設定に使うUTC日単位の実行上限</td></tr><tr><td>MAX_CONCURRENT</td><td>初回設定に使う同時実行数</td></tr><tr><td>DEPLOYMENT_TIER</td><td>Previewだけpreviewを指定</td></tr><tr><td>PREVIEW_MODEL_MODE</td><td>Previewのstubでテスト値を使用</td></tr><tr><td>PREVIEW_ACCESS_DOMAIN / AUD</td><td>Accessの信頼する発行元と対象アプリ</td></tr></tbody></table><p>モデルと予算は初回登録時に管理DBへ引き継ぎます。以後の設定元はSuperuserの「JevSense管理」です。環境変数だけを書き換えてDBの値を上書きする運用ではありません。</p><h2 id="管理画面の主要設定" tabindex="-1">管理画面の主要設定 <a class="header-anchor" href="#管理画面の主要設定" aria-label="Permalink to “管理画面の主要設定”">​</a></h2><table tabindex="0"><thead><tr><th>設定</th><th>範囲</th></tr></thead><tbody><tr><td>サイトのOrigin</td><td>最大10件</td></tr><tr><td>サイト</td><td>最大100</td></tr><tr><td>公開設定の施策</td><td>サイトあたり最大5</td></tr><tr><td>質問</td><td>施策あたり最大5、サイト合計最大10</td></tr><tr><td>案内内容・各条件</td><td>各400文字以内</td></tr><tr><td>判定閾値</td><td>0.5〜0.99。厳密に上回る場合</td></tr><tr><td>表示回数</td><td>1〜10</td></tr><tr><td>優先順位</td><td>0〜100</td></tr><tr><td>有効閲覧時間</td><td>1000〜300000ミリ秒</td></tr><tr><td>必要な有効閲覧数</td><td>1〜10</td></tr><tr><td>保存下書き</td><td>サイトあたり最大20</td></tr><tr><td>パスキー</td><td>ユーザーあたり最大10</td></tr></tbody></table><h2 id="入力・通信の上限" tabindex="-1">入力・通信の上限 <a class="header-anchor" href="#入力・通信の上限" aria-label="Permalink to “入力・通信の上限”">​</a></h2><p>要求本文は64KiB。有効な閲覧履歴は最大50件、任意イベントは最大30件、確定状態は最大20項目です。上限内でもページ情報の長さによって本文サイズの上限に達する場合があります。</p><p>許可された名前・経路・型だけを使い、未知の値や不正な確率は表示対象としない設計です。</p><h2 id="期限" tabindex="-1">期限 <a class="header-anchor" href="#期限" aria-label="Permalink to “期限”">​</a></h2><table tabindex="0"><thead><tr><th>対象</th><th>期限・扱い</th></tr></thead><tbody><tr><td>管理セッション</td><td>無操作30分、絶対12時間</td></tr><tr><td>重要操作の再認証</td><td>5分以内</td></tr><tr><td>招待リンク</td><td>24時間、1回限り</td></tr><tr><td>Superuserの復旧リンク</td><td>5分、1回限り</td></tr><tr><td>認証challenge</td><td>5分、1回限り</td></tr><tr><td>実ページ確認チケット</td><td>5分、1回限り</td></tr><tr><td>独自コードの確認用取得権限</td><td>30秒、1回限り</td></tr><tr><td>診断認可</td><td>最長15分</td></tr></tbody></table><h2 id="apiの大まかな役割" tabindex="-1">APIの大まかな役割 <a class="header-anchor" href="#apiの大まかな役割" aria-label="Permalink to “APIの大まかな役割”">​</a></h2><p>公開SDKは<code>/v1/sites/:siteId</code>、<code>/v1/decision</code>等を使います。管理者のログインは<code>/auth/*</code>、サイト別管理は<code>/admin/api/v2/*</code>です。</p><p>管理Cookieや管理トークンをSDKへ配らないでください。実際のスキーマと競合制御は<a href="https://github.com/manji6/jev-personalization/blob/feature/admin-v2-implementation/docs/admin-v2-design.md" target="_blank" rel="noreferrer">詳細設計</a>を参照してください。</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};